def basis(r, c, deg):
    r = np.asarray(r) / 15 * 2 - 1
    c = np.asarray(c) / 23 * 2 - 1
    cols = [np.ones(len(r)), r, c, r * r, c * c, r * c]
    if deg >= 3:
        cols += [r ** 3, c ** 3, r * r * c, r * c * c]
    if deg >= 4:
        cols += [r ** 4, c ** 4, r ** 3 * c, r * c ** 3, r * r * c * c]
    return np.column_stack(cols)

def b(r, c):
    r = np.asarray(r) / 15 * 2 - 1
    c = np.asarray(c) / 23 * 2 - 1
    return np.column_stack([np.ones(len(r)), r, c, r * r, c * c, r * c, r ** 4, c ** 4, r ** 3 * c, r * c ** 3, r * r * c * c])

def surf(r, c):
    r = np.asarray(r) / 15 * 2 - 1
    c = np.asarray(c) / 23 * 2 - 1
    return np.column_stack([np.ones(len(r)), r, c, r * r, c * c, r * c])

def hill(q, c):
    (ic, s) = q
    return 1 / (1 + 10 ** (s * (c - ic)))
